using Microsoft.Data.Sqlite;
using System.Text.Json;
namespace WinGuardAgent.Storage;
public sealed class Database { public string ConnectionString=>$"Data Source={Paths.Database};Cache=Shared"; public async Task InitializeAsync(CancellationToken ct=default){Directory.CreateDirectory(Paths.ProgramData);Directory.CreateDirectory(Paths.LogDirectory);await using var c=new SqliteConnection(ConnectionString);await c.OpenAsync(ct);var cmd=c.CreateCommand();cmd.CommandText="PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS Policies(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Json TEXT NOT NULL, Enabled INTEGER NOT NULL DEFAULT 1); CREATE TABLE IF NOT EXISTS BlockedDomains(Id INTEGER PRIMARY KEY, Domain TEXT NOT NULL UNIQUE, IsAllowed INTEGER NOT NULL DEFAULT 0, Category TEXT NOT NULL, Enabled INTEGER NOT NULL DEFAULT 1, Source TEXT NOT NULL DEFAULT 'local'); CREATE TABLE IF NOT EXISTS BlockedApplications(Id INTEGER PRIMARY KEY, ExecutableName TEXT NOT NULL UNIQUE, Path TEXT, Enabled INTEGER NOT NULL DEFAULT 1, Reason TEXT NOT NULL DEFAULT 'Administrator policy', Category TEXT NOT NULL DEFAULT 'Custom'); CREATE TABLE IF NOT EXISTS Events(Id INTEGER PRIMARY KEY, Timestamp TEXT NOT NULL, Type TEXT NOT NULL, Username TEXT, Subject TEXT, Reason TEXT, MetadataJson TEXT); CREATE TABLE IF NOT EXISTS InstalledApplications(AppKey TEXT PRIMARY KEY, Name TEXT NOT NULL, Publisher TEXT, Version TEXT, InstallTimestamp TEXT, Path TEXT); CREATE TABLE IF NOT EXISTS AgentSettings(Key TEXT PRIMARY KEY, Value TEXT NOT NULL); CREATE TABLE IF NOT EXISTS AgentStatus(Key TEXT PRIMARY KEY, Value TEXT NOT NULL);";await cmd.ExecuteNonQueryAsync(ct);} }
public sealed class PolicyRepository(Database db){ public Task InitializeAsync(CancellationToken ct=default)=>db.InitializeAsync(ct); public async Task AddDomainAsync(string domain,bool allowed=false,PolicyCategory category=PolicyCategory.Custom,CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO BlockedDomains(Domain,IsAllowed,Category,Enabled) VALUES($d,$a,$c,1) ON CONFLICT(Domain) DO UPDATE SET IsAllowed=$a,Category=$c,Enabled=1";q.Parameters.AddWithValue("$d",domain.Trim().ToLowerInvariant());q.Parameters.AddWithValue("$a",allowed?1:0);q.Parameters.AddWithValue("$c",category.ToString());await q.ExecuteNonQueryAsync(ct);} public async Task RemoveDomainAsync(string domain,CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="DELETE FROM BlockedDomains WHERE Domain=$d";q.Parameters.AddWithValue("$d",domain.Trim().ToLowerInvariant());await q.ExecuteNonQueryAsync(ct);} public async Task AddAppAsync(string exe,CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO BlockedApplications(ExecutableName) VALUES($e) ON CONFLICT(ExecutableName) DO UPDATE SET Enabled=1";q.Parameters.AddWithValue("$e",Path.GetFileName(exe).ToLowerInvariant());await q.ExecuteNonQueryAsync(ct);} public async Task RemoveAppAsync(string exe,CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="DELETE FROM BlockedApplications WHERE ExecutableName=$e";q.Parameters.AddWithValue("$e",Path.GetFileName(exe).ToLowerInvariant());await q.ExecuteNonQueryAsync(ct);} public async Task<HashSet<string>> GetBlockedAppsAsync(CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="SELECT ExecutableName FROM BlockedApplications WHERE Enabled=1";var set=new HashSet<string>(StringComparer.OrdinalIgnoreCase);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))set.Add(r.GetString(0));return set;} }
public sealed class EventRepository(Database db){ public async Task WriteAsync(string type,string? username=null,string? subject=null,string? reason=null,string? metadata=null,CancellationToken ct=default){await db.InitializeAsync(ct);await using var c=new SqliteConnection(db.ConnectionString);await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO Events(Timestamp,Type,Username,Subject,Reason,MetadataJson) VALUES($t,$y,$u,$s,$r,$m)";q.Parameters.AddWithValue("$t",DateTimeOffset.UtcNow.ToString("o"));q.Parameters.AddWithValue("$y",type);q.Parameters.AddWithValue("$u",(object?)username??DBNull.Value);q.Parameters.AddWithValue("$s",(object?)subject??DBNull.Value);q.Parameters.AddWithValue("$r",(object?)reason??DBNull.Value);q.Parameters.AddWithValue("$m",(object?)metadata??DBNull.Value);await q.ExecuteNonQueryAsync(ct);} }
public sealed class SettingsRepository(Database db){ public async Task<AgentConfig> GetAsync(CancellationToken ct=default){await db.InitializeAsync(ct);if(!File.Exists(Paths.ConfigFile)){var d=new AgentConfig();await File.WriteAllTextAsync(Paths.ConfigFile,JsonSerializer.Serialize(d,new JsonSerializerOptions{WriteIndented=true}),ct);return d;}return JsonSerializer.Deserialize<AgentConfig>(await File.ReadAllTextAsync(Paths.ConfigFile,ct))??new AgentConfig();} }
public sealed class AgentStatusRepository(Database db){ public Task InitializeAsync(CancellationToken ct=default)=>db.InitializeAsync(ct); }